"""Greedy rewrite infrastructure used by the pass manager."""

from __future__ import annotations

from typing import Iterable, List

from .ir import IntegerType, Operation


class PatternRewriter:
    """Helpers used by rewrite patterns."""

    def replace_op_with_constant(self, op: Operation, value: int) -> Operation:
        if op.parent_block is None:
            raise ValueError("cannot rewrite detached operation")
        block = op.parent_block
        index = block.operations.index(op)
        result = op.result
        if not isinstance(result.type, IntegerType):
            raise ValueError("constant folding only supports integer results")
        constant = Operation(
            "arith.constant",
            result_types=[result.type],
            attributes={"value": value},
            properties={"type": result.type},
            result_names=[result.name_hint or ""],
        )
        if constant.results[0].name_hint == "":
            constant.results[0].name_hint = result.name_hint
        block.insert_op(index, constant)
        result.replace_all_uses_with(constant.result)
        op.erase()
        return constant


class RewritePattern:
    """Base class for patterns applied by the greedy rewriter."""

    def match_and_rewrite(self, op: Operation, rewriter: PatternRewriter) -> bool:
        raise NotImplementedError


class GreedyPatternApplier:
    """Repeatedly applies patterns until a fixed point is reached."""

    def __init__(self, patterns: Iterable[RewritePattern]) -> None:
        self._patterns: List[RewritePattern] = list(patterns)

    def run(self, module: Operation) -> int:
        rewrites = 0
        changed = True
        while changed:
            changed = False
            for op in list(module.walk()):
                if op.name in {"builtin.module", "func.func", "hw.module"}:
                    continue
                for pattern in self._patterns:
                    rewriter = PatternRewriter()
                    if pattern.match_and_rewrite(op, rewriter):
                        rewrites += 1
                        changed = True
                        break
                if changed:
                    break
        return rewrites

