"""Parser for the small MLIR/CIRCT subset used by the repository."""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Dict, List, Optional, Sequence

from .ir import (
    Block,
    ClockType,
    ForwardValue,
    IntegerType,
    ModuleOp,
    Operation,
    Region,
    Type,
    make_function_op,
    make_hw_module_op,
)


_COMMENT_RE = re.compile(r"//.*$")
_FUNC_RE = re.compile(r"func\.func\s+@([A-Za-z_][\w$.]*)\((.*)\)(?:\s*->\s*(.+?))?\s*\{$")
_HW_MODULE_RE = re.compile(r"hw\.module\s+@([A-Za-z_][\w$.]*)\((.*)\)\s*\{$")
_BLOCK_RE = re.compile(r"\^([\w$.]+)(?:\((.*)\))?:$")


class ParseError(ValueError):
    """Raised when the textual parser encounters malformed input."""


@dataclass
class _Scope:
    values: Dict[str, object]
    unresolved: Dict[str, ForwardValue]


class Parser:
    """Line-oriented parser for the subset exercised by the repo."""

    def __init__(self, source: str) -> None:
        self._lines = source.splitlines()
        self._index = 0
        self._scopes: List[_Scope] = []

    def parse(self) -> ModuleOp:
        self._skip_noise()
        line = self._peek_line()
        if line != "module {":
            raise ParseError("expected top-level 'module {'")
        self._consume_line()
        module = ModuleOp(Region([Block()]))
        self._parse_region(module.regions[0], block_arguments=None)
        self._expect_line("}")
        self._ensure_done()
        return module

    def _parse_region(
        self,
        region: Region,
        block_arguments: Optional[Sequence[tuple[str, Type]]],
    ) -> None:
        if block_arguments is not None:
            region.blocks.clear()
            region.add_block(Block(arguments=block_arguments))
        self._scopes.append(_Scope(values={}, unresolved={}))
        try:
            if block_arguments:
                for block_argument in region.entry_block.arguments:
                    self._define_value(block_argument.name_hint or "", block_argument)
            current_block = region.entry_block
            while True:
                self._skip_noise()
                line = self._peek_line()
                if line is None or line == "}":
                    break
                block_match = _BLOCK_RE.match(line)
                if block_match:
                    block_name = block_match.group(1)
                    arguments = self._parse_argument_list(block_match.group(2) or "")
                    if (
                        len(region.blocks) == 1
                        and not current_block.operations
                        and not current_block.arguments
                        and current_block.label is None
                    ):
                        current_block.label = block_name
                        for arg_name, arg_type in arguments:
                            current_block.add_argument(arg_name, arg_type)
                            self._define_value(arg_name, current_block.arguments[-1])
                    else:
                        current_block = Block(label=block_name, arguments=arguments)
                        region.add_block(current_block)
                        for block_argument in current_block.arguments:
                            self._define_value(block_argument.name_hint or "", block_argument)
                    self._consume_line()
                    continue
                op = self._parse_operation_line(line)
                current_block.append_op(op)
                self._consume_line()
        finally:
            scope = self._scopes.pop()
            if scope.unresolved:
                names = ", ".join(sorted(scope.unresolved))
                raise ParseError(f"unresolved SSA values: {names}")

    def _parse_operation_line(self, line: str) -> Operation:
        result_names: List[str] = []
        op_text = line
        if "=" in line:
            left, right = line.split("=", 1)
            if left.strip().startswith("%"):
                result_names = [name.strip()[1:] for name in left.split(",")]
                op_text = right.strip()
        if " " in op_text:
            op_name, rest = op_text.split(" ", 1)
        else:
            op_name, rest = op_text, ""

        dispatch = {
            "module": self._parse_module_op,
            "func.func": self._parse_func_op,
            "hw.module": self._parse_hw_module_op,
            "arith.constant": self._parse_constant_op,
            "hw.constant": self._parse_constant_op,
            "arith.addi": self._parse_binary_op,
            "arith.subi": self._parse_binary_op,
            "arith.muli": self._parse_binary_op,
            "comb.add": self._parse_binary_op,
            "comb.and": self._parse_binary_op,
            "comb.or": self._parse_binary_op,
            "comb.xor": self._parse_binary_op,
            "arith.cmpi": self._parse_cmp_op,
            "comb.icmp": self._parse_cmp_op,
            "comb.mux": self._parse_mux_op,
            "cf.br": self._parse_branch_op,
            "cf.cond_br": self._parse_cond_branch_op,
            "return": self._parse_terminator_with_values,
            "func.return": self._parse_terminator_with_values,
            "hw.output": self._parse_terminator_with_values,
            "seq.compreg": self._parse_compreg_op,
        }
        if op_name not in dispatch:
            raise ParseError(f"unsupported operation '{op_name}'")
        operation = dispatch[op_name](op_name, rest.strip(), result_names)
        for index, result_name in enumerate(result_names):
            operation.results[index].name_hint = result_name
            self._define_value(result_name, operation.results[index])
        return operation

    def _parse_module_op(self, op_name: str, rest: str, result_names: List[str]) -> Operation:
        if rest != "{":
            raise ParseError("nested module must end with '{'")
        region = Region([Block()])
        operation = ModuleOp(region)
        self._consume_line()
        self._parse_region(operation.regions[0], block_arguments=None)
        self._expect_line("}")
        return operation

    def _parse_func_op(self, op_name: str, rest: str, result_names: List[str]) -> Operation:
        match = _FUNC_RE.match(f"{op_name} {rest}")
        if match is None:
            raise ParseError("malformed func.func signature")
        name = match.group(1)
        arguments = self._parse_argument_list(match.group(2))
        results = self._parse_result_types(match.group(3))
        operation = make_function_op(name, arguments, results)
        self._consume_line()
        self._parse_region(operation.regions[0], block_arguments=arguments)
        self._expect_line("}")
        return operation

    def _parse_hw_module_op(self, op_name: str, rest: str, result_names: List[str]) -> Operation:
        match = _HW_MODULE_RE.match(f"{op_name} {rest}")
        if match is None:
            raise ParseError("malformed hw.module signature")
        name = match.group(1)
        ports = self._parse_port_list(match.group(2))
        operation = make_hw_module_op(name, ports)
        self._consume_line()
        input_args = [
            (port["name"], port["type"])
            for port in ports
            if port["direction"] == "in"
        ]
        self._parse_region(operation.regions[0], block_arguments=input_args)
        self._expect_line("}")
        return operation

    def _parse_constant_op(self, op_name: str, rest: str, result_names: List[str]) -> Operation:
        value_text, type_text = self._split_once(rest, ":")
        op_type = self._parse_type(type_text.strip())
        value = int(value_text.strip())
        return Operation(
            op_name,
            result_types=[op_type],
            attributes={"value": value},
            properties={"type": op_type},
            result_names=result_names,
        )

    def _parse_binary_op(self, op_name: str, rest: str, result_names: List[str]) -> Operation:
        operands_text, type_text = self._split_once(rest, ":")
        operands = [self._lookup_value(name) for name in self._parse_value_refs(operands_text)]
        op_type = self._parse_type(type_text.strip())
        return Operation(
            op_name,
            operands=operands,
            result_types=[op_type],
            properties={"type": op_type},
            result_names=result_names,
        )

    def _parse_cmp_op(self, op_name: str, rest: str, result_names: List[str]) -> Operation:
        predicate, remaining = self._split_once(rest, ",")
        operands_text, operand_type_text = self._split_once(remaining, ":")
        operands = [self._lookup_value(name) for name in self._parse_value_refs(operands_text)]
        operand_type = self._parse_type(operand_type_text.strip())
        return Operation(
            op_name,
            operands=operands,
            result_types=[IntegerType(1)],
            attributes={"predicate": predicate.strip()},
            properties={"operand_type": operand_type},
            result_names=result_names,
        )

    def _parse_mux_op(self, op_name: str, rest: str, result_names: List[str]) -> Operation:
        operands_text, type_text = self._split_once(rest, ":")
        operand_names = self._parse_value_refs(operands_text)
        if len(operand_names) != 3:
            raise ParseError("comb.mux expects three operands")
        operands = [self._lookup_value(name) for name in operand_names]
        op_type = self._parse_type(type_text.strip())
        return Operation(
            op_name,
            operands=operands,
            result_types=[op_type],
            properties={"type": op_type},
            result_names=result_names,
        )

    def _parse_branch_op(self, op_name: str, rest: str, result_names: List[str]) -> Operation:
        target = rest.strip()
        if not target.startswith("^"):
            raise ParseError("cf.br expects a block label")
        return Operation(op_name, successors=[target[1:]])

    def _parse_cond_branch_op(self, op_name: str, rest: str, result_names: List[str]) -> Operation:
        parts = [part.strip() for part in rest.split(",")]
        if len(parts) != 3:
            raise ParseError("cf.cond_br expects a condition and two block labels")
        condition = self._lookup_value(parts[0][1:] if parts[0].startswith("%") else parts[0])
        targets = []
        for part in parts[1:]:
            if not part.startswith("^"):
                raise ParseError("cf.cond_br expects block labels")
            targets.append(part[1:])
        return Operation(op_name, operands=[condition], successors=targets)

    def _parse_terminator_with_values(
        self,
        op_name: str,
        rest: str,
        result_names: List[str],
    ) -> Operation:
        if not rest:
            return Operation(op_name)
        operands_text, type_text = self._split_once(rest, ":")
        operand_names = self._parse_value_refs(operands_text)
        operands = [self._lookup_value(name) for name in operand_names]
        operand_type = self._parse_type(type_text.strip())
        return Operation(op_name, operands=operands, properties={"type": operand_type})

    def _parse_compreg_op(self, op_name: str, rest: str, result_names: List[str]) -> Operation:
        operands_text, type_text = self._split_once(rest, ":")
        if " reset " in operands_text:
            lead, reset_tail = operands_text.split(" reset ", 1)
            input_name, clock_name = self._parse_value_refs(lead)
            reset_name, reset_value_name = self._parse_value_refs(reset_tail)
            operands = [
                self._lookup_value(input_name),
                self._lookup_value(clock_name),
                self._lookup_value(reset_name),
                self._lookup_value(reset_value_name),
            ]
            has_reset = True
        else:
            input_name, clock_name = self._parse_value_refs(operands_text)
            operands = [self._lookup_value(input_name), self._lookup_value(clock_name)]
            has_reset = False
        op_type = self._parse_type(type_text.strip())
        return Operation(
            op_name,
            operands=operands,
            result_types=[op_type],
            properties={"type": op_type, "has_reset": has_reset},
            result_names=result_names,
        )

    def _parse_argument_list(self, text: str) -> List[tuple[str, Type]]:
        if not text.strip():
            return []
        arguments: List[tuple[str, Type]] = []
        for item in self._split_top_level(text):
            name_text, type_text = self._split_once(item, ":")
            name = name_text.strip()
            if not name.startswith("%"):
                raise ParseError("block and function arguments must use SSA names")
            arguments.append((name[1:], self._parse_type(type_text.strip())))
        return arguments

    def _parse_port_list(self, text: str) -> List[Dict[str, object]]:
        if not text.strip():
            return []
        ports: List[Dict[str, object]] = []
        for item in self._split_top_level(text):
            item = item.strip()
            if item.startswith("in "):
                direction = "in"
                name_text, type_text = self._split_once(item[3:].strip(), ":")
                name = name_text.strip()
                if not name.startswith("%"):
                    raise ParseError("input ports must use SSA syntax")
                ports.append(
                    {"direction": direction, "name": name[1:], "type": self._parse_type(type_text.strip())}
                )
            elif item.startswith("out "):
                direction = "out"
                name_text, type_text = self._split_once(item[4:].strip(), ":")
                name = name_text.strip()
                if name.startswith("%"):
                    name = name[1:]
                ports.append(
                    {"direction": direction, "name": name, "type": self._parse_type(type_text.strip())}
                )
            else:
                raise ParseError("ports must start with 'in' or 'out'")
        return ports

    def _parse_result_types(self, text: Optional[str]) -> List[Type]:
        if text is None:
            return []
        text = text.strip()
        if not text:
            return []
        if text.startswith("(") and text.endswith(")"):
            inner = text[1:-1].strip()
            if not inner:
                return []
            return [self._parse_type(item.strip()) for item in self._split_top_level(inner)]
        return [self._parse_type(text)]

    def _parse_type(self, text: str) -> Type:
        text = text.strip()
        if text.startswith("i") and text[1:].isdigit():
            return IntegerType(int(text[1:]))
        if text == "!seq.clock":
            return ClockType()
        raise ParseError(f"unsupported type '{text}'")

    def _parse_value_refs(self, text: str) -> List[str]:
        refs: List[str] = []
        for item in self._split_top_level(text):
            token = item.strip()
            if not token:
                continue
            if not token.startswith("%"):
                raise ParseError(f"expected SSA value, got '{token}'")
            refs.append(token[1:])
        return refs

    def _lookup_value(self, name: str):
        scope = self._scopes[-1]
        if name in scope.values:
            return scope.values[name]
        if name not in scope.unresolved:
            scope.unresolved[name] = ForwardValue(name)
        return scope.unresolved[name]

    def _define_value(self, name: str, value) -> None:
        scope = self._scopes[-1]
        if name in scope.unresolved:
            scope.unresolved.pop(name).replace_all_uses_with(value)
        scope.values[name] = value

    def _skip_noise(self) -> None:
        while self._index < len(self._lines):
            line = _COMMENT_RE.sub("", self._lines[self._index]).rstrip()
            if line.strip():
                break
            self._index += 1

    def _peek_line(self) -> Optional[str]:
        self._skip_noise()
        if self._index >= len(self._lines):
            return None
        return _COMMENT_RE.sub("", self._lines[self._index]).strip()

    def _consume_line(self) -> None:
        self._index += 1

    def _expect_line(self, expected: str) -> None:
        line = self._peek_line()
        if line != expected:
            raise ParseError(f"expected '{expected}', got '{line}'")
        self._consume_line()

    def _ensure_done(self) -> None:
        self._skip_noise()
        if self._index != len(self._lines):
            raise ParseError("unexpected trailing input")

    @staticmethod
    def _split_once(text: str, needle: str) -> tuple[str, str]:
        if needle not in text:
            raise ParseError(f"expected '{needle}' in '{text}'")
        left, right = text.split(needle, 1)
        return left.strip(), right.strip()

    @staticmethod
    def _split_top_level(text: str) -> List[str]:
        parts: List[str] = []
        depth = 0
        current: List[str] = []
        for char in text:
            if char == "," and depth == 0:
                part = "".join(current).strip()
                if part:
                    parts.append(part)
                current = []
                continue
            current.append(char)
            if char in "(<[":
                depth += 1
            elif char in ")>]":
                depth -= 1
        tail = "".join(current).strip()
        if tail:
            parts.append(tail)
        return parts


def parse(source: str) -> ModuleOp:
    """Parse textual MLIR into the generic IR."""

    return Parser(source).parse()

