"""Printer for the small MLIR/CIRCT subset used by the repo."""

from __future__ import annotations

from typing import Dict, List

from .ir import Block, ModuleOp, Operation, Value


class Printer:
    """Pretty printer for the generic IR."""

    def __init__(self) -> None:
        self._value_names: Dict[int, str] = {}
        self._next_value_id = 0

    def print_module(self, module: ModuleOp) -> str:
        lines: List[str] = []
        self._print_op(module, lines, indent=0)
        return "\n".join(lines)

    def _print_op(self, op: Operation, lines: List[str], indent: int) -> None:
        pad = "  " * indent
        if op.name == "builtin.module":
            lines.append(f"{pad}module {{")
            self._print_region(op.regions[0], lines, indent + 1)
            lines.append(f"{pad}}}")
            return
        if op.name == "func.func":
            args = ", ".join(
                f"%{name}: {arg_type}"
                for name, arg_type in zip(op.properties["arg_names"], op.properties["arg_types"])
            )
            result_types = op.properties["result_types"]
            if not result_types:
                signature = ""
            elif len(result_types) == 1:
                signature = f" -> {result_types[0]}"
            else:
                signature = f" -> ({', '.join(str(result) for result in result_types)})"
            lines.append(f"{pad}func.func @{op.properties['sym_name']}({args}){signature} {{")
            self._print_region(op.regions[0], lines, indent + 1)
            lines.append(f"{pad}}}")
            return
        if op.name == "hw.module":
            ports = []
            for port in op.properties["ports"]:
                if port["direction"] == "in":
                    ports.append(f"in %{port['name']}: {port['type']}")
                else:
                    ports.append(f"out {port['name']}: {port['type']}")
            lines.append(f"{pad}hw.module @{op.properties['sym_name']}({', '.join(ports)}) {{")
            self._print_region(op.regions[0], lines, indent + 1)
            lines.append(f"{pad}}}")
            return
        lines.append(f"{pad}{self._format_generic_op(op)}")

    def _print_region(self, region, lines: List[str], indent: int) -> None:
        for index, block in enumerate(region.blocks):
            if index == 0 and block.label is None:
                self._print_block_body(block, lines, indent)
                continue
            self._print_block_header(block, lines, indent)
            self._print_block_body(block, lines, indent)

    def _print_block_header(self, block: Block, lines: List[str], indent: int) -> None:
        pad = "  " * indent
        header = f"{pad}^{block.label or 'bb'}"
        if block.arguments:
            args = ", ".join(f"%{arg.name_hint}: {arg.type}" for arg in block.arguments)
            header += f"({args})"
        header += ":"
        lines.append(header)

    def _print_block_body(self, block: Block, lines: List[str], indent: int) -> None:
        for op in block.operations:
            self._print_op(op, lines, indent)

    def _format_generic_op(self, op: Operation) -> str:
        prefix = ""
        if op.results:
            prefix = ", ".join(self._value_name(result) for result in op.results) + " = "
        if op.name in {"arith.constant", "hw.constant"}:
            return f"{prefix}{op.name} {op.attributes['value']} : {op.properties['type']}"
        if op.name in {
            "arith.addi",
            "arith.subi",
            "arith.muli",
            "comb.add",
            "comb.and",
            "comb.or",
            "comb.xor",
        }:
            operands = ", ".join(self._value_name(operand) for operand in op.operands)
            return f"{prefix}{op.name} {operands} : {op.properties['type']}"
        if op.name in {"arith.cmpi", "comb.icmp"}:
            operands = ", ".join(self._value_name(operand) for operand in op.operands)
            return (
                f"{prefix}{op.name} {op.attributes['predicate']}, "
                f"{operands} : {op.properties['operand_type']}"
            )
        if op.name == "comb.mux":
            operands = ", ".join(self._value_name(operand) for operand in op.operands)
            return f"{prefix}{op.name} {operands} : {op.properties['type']}"
        if op.name == "cf.br":
            return f"{prefix}{op.name} ^{op.successors[0]}"
        if op.name == "cf.cond_br":
            condition = self._value_name(op.operands[0])
            return f"{prefix}{op.name} {condition}, ^{op.successors[0]}, ^{op.successors[1]}"
        if op.name in {"return", "func.return", "hw.output"}:
            if not op.operands:
                return f"{prefix}{op.name}"
            operands = ", ".join(self._value_name(operand) for operand in op.operands)
            return f"{prefix}{op.name} {operands} : {op.properties['type']}"
        if op.name == "seq.compreg":
            input_name = self._value_name(op.operands[0])
            clock_name = self._value_name(op.operands[1])
            if op.properties["has_reset"]:
                reset_name = self._value_name(op.operands[2])
                reset_value_name = self._value_name(op.operands[3])
                suffix = f"{input_name}, {clock_name} reset {reset_name}, {reset_value_name}"
            else:
                suffix = f"{input_name}, {clock_name}"
            return f"{prefix}{op.name} {suffix} : {op.properties['type']}"
        raise ValueError(f"unsupported operation for printing: {op.name}")

    def _value_name(self, value: Value) -> str:
        if value.name_hint:
            return f"%{value.name_hint}"
        key = id(value)
        if key not in self._value_names:
            self._value_names[key] = f"%{self._next_value_id}"
            self._next_value_id += 1
        return self._value_names[key]


def print_module(module: ModuleOp) -> str:
    """Print a module in textual form."""

    return Printer().print_module(module)

