"""Core MLIR-style IR data structures used across the stack."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Dict, Iterable, Iterator, List, Optional, Sequence


@dataclass(frozen=True)
class Type:
    """Base type marker."""

    spelling: str

    def __str__(self) -> str:
        return self.spelling


@dataclass(frozen=True)
class IntegerType(Type):
    """Signless integer type."""

    width: int

    def __init__(self, width: int) -> None:
        object.__setattr__(self, "width", width)
        object.__setattr__(self, "spelling", f"i{width}")


@dataclass(frozen=True)
class ClockType(Type):
    """Clock type used by the seq dialect."""

    def __init__(self) -> None:
        object.__setattr__(self, "spelling", "!seq.clock")


@dataclass(frozen=True)
class FunctionType(Type):
    """Function signature type."""

    inputs: tuple[Type, ...]
    results: tuple[Type, ...]

    def __init__(self, inputs: Sequence[Type], results: Sequence[Type]) -> None:
        object.__setattr__(self, "inputs", tuple(inputs))
        object.__setattr__(self, "results", tuple(results))
        if len(self.results) == 1:
            result_spelling = str(self.results[0])
        else:
            result_spelling = f"({', '.join(str(result) for result in self.results)})"
        object.__setattr__(
            self,
            "spelling",
            f"({', '.join(str(arg) for arg in self.inputs)}) -> {result_spelling}",
        )


class Value:
    """Base SSA value."""

    def __init__(self, value_type: Optional[Type], name_hint: Optional[str] = None) -> None:
        self.type = value_type
        self.name_hint = name_hint
        self._uses: List[tuple["Operation", int]] = []

    @property
    def uses(self) -> List[tuple["Operation", int]]:
        return list(self._uses)

    def add_use(self, owner: "Operation", index: int) -> None:
        self._uses.append((owner, index))

    def remove_use(self, owner: "Operation", index: int) -> None:
        self._uses = [use for use in self._uses if use != (owner, index)]

    def replace_all_uses_with(self, other: "Value") -> None:
        for owner, index in list(self._uses):
            owner.set_operand(index, other)

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}({self.name_hint!r}, {self.type})"


class BlockArgument(Value):
    """A value defined by a block argument."""

    def __init__(
        self,
        value_type: Type,
        block: "Block",
        index: int,
        name_hint: Optional[str] = None,
    ) -> None:
        super().__init__(value_type, name_hint)
        self.block = block
        self.index = index


class OpResult(Value):
    """A value defined by an operation result."""

    def __init__(
        self,
        value_type: Type,
        owner: "Operation",
        index: int,
        name_hint: Optional[str] = None,
    ) -> None:
        super().__init__(value_type, name_hint)
        self.owner = owner
        self.index = index


class ForwardValue(Value):
    """Placeholder used to support forward references during parsing."""

    def __init__(self, name_hint: str) -> None:
        super().__init__(None, name_hint=name_hint)


class Region:
    """A region contains an ordered list of blocks."""

    def __init__(self, blocks: Optional[Iterable["Block"]] = None) -> None:
        self.blocks: List[Block] = []
        self.parent_op: Optional[Operation] = None
        if blocks:
            for block in blocks:
                self.add_block(block)

    def add_block(self, block: "Block") -> None:
        block.parent_region = self
        self.blocks.append(block)

    @property
    def entry_block(self) -> "Block":
        if not self.blocks:
            raise ValueError("region has no blocks")
        return self.blocks[0]

    def __iter__(self) -> Iterator["Block"]:
        return iter(self.blocks)


class Block:
    """A basic block."""

    def __init__(
        self,
        label: Optional[str] = None,
        arguments: Optional[Sequence[tuple[str, Type]]] = None,
    ) -> None:
        self.label = label
        self.arguments: List[BlockArgument] = []
        self.operations: List[Operation] = []
        self.parent_region: Optional[Region] = None
        for name, arg_type in arguments or []:
            self.add_argument(name, arg_type)

    def add_argument(self, name: str, arg_type: Type) -> BlockArgument:
        argument = BlockArgument(arg_type, self, len(self.arguments), name_hint=name)
        self.arguments.append(argument)
        return argument

    def append_op(self, op: "Operation") -> None:
        op.parent_block = self
        self.operations.append(op)

    def insert_op(self, index: int, op: "Operation") -> None:
        op.parent_block = self
        self.operations.insert(index, op)

    def remove_op(self, op: "Operation") -> None:
        self.operations.remove(op)
        op.parent_block = None

    def __iter__(self) -> Iterator["Operation"]:
        return iter(self.operations)


class Operation:
    """Generic MLIR-style operation."""

    def __init__(
        self,
        name: str,
        operands: Optional[Sequence[Value]] = None,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Any]] = None,
        regions: Optional[Sequence[Region]] = None,
        successors: Optional[Sequence[str]] = None,
        properties: Optional[Dict[str, Any]] = None,
        result_names: Optional[Sequence[str]] = None,
    ) -> None:
        self.name = name
        self.operands: List[Value] = []
        self.results: List[OpResult] = []
        self.attributes = dict(attributes or {})
        self.regions: List[Region] = []
        self.successors = list(successors or [])
        self.properties = dict(properties or {})
        self.parent_block: Optional[Block] = None

        for index, operand in enumerate(operands or []):
            self.operands.append(operand)
            operand.add_use(self, index)

        names = list(result_names or [])
        for index, result_type in enumerate(result_types or []):
            name_hint = names[index] if index < len(names) else None
            self.results.append(OpResult(result_type, self, index, name_hint=name_hint))

        for region in regions or []:
            self.add_region(region)

    def add_region(self, region: Region) -> None:
        region.parent_op = self
        self.regions.append(region)

    def set_operand(self, index: int, value: Value) -> None:
        old_value = self.operands[index]
        old_value.remove_use(self, index)
        self.operands[index] = value
        value.add_use(self, index)

    @property
    def result(self) -> OpResult:
        if len(self.results) != 1:
            raise ValueError("operation does not have exactly one result")
        return self.results[0]

    def erase(self) -> None:
        if self.parent_block is None:
            raise ValueError("cannot erase detached operation")
        self.parent_block.remove_op(self)
        for index, operand in enumerate(list(self.operands)):
            operand.remove_use(self, index)

    def walk(self) -> Iterator["Operation"]:
        yield self
        for region in self.regions:
            for block in region.blocks:
                for op in block.operations:
                    yield from op.walk()

    def __repr__(self) -> str:
        return f"Operation({self.name!r})"


class ModuleOp(Operation):
    """Top-level module operation."""

    def __init__(self, region: Optional[Region] = None) -> None:
        super().__init__("builtin.module", regions=[region or Region([Block()])])

    @property
    def body(self) -> Block:
        return self.regions[0].entry_block


def make_function_op(
    name: str,
    arguments: Sequence[tuple[str, Type]],
    results: Sequence[Type],
    region: Optional[Region] = None,
) -> Operation:
    """Create a function operation backed by the generic IR."""

    function_region = region or Region([Block(arguments=arguments)])
    return Operation(
        "func.func",
        regions=[function_region],
        properties={
            "sym_name": name,
            "arg_names": [arg_name for arg_name, _ in arguments],
            "arg_types": [arg_type for _, arg_type in arguments],
            "result_types": list(results),
            "function_type": FunctionType([arg_type for _, arg_type in arguments], results),
        },
    )


def make_hw_module_op(
    name: str,
    ports: Sequence[Dict[str, Any]],
    region: Optional[Region] = None,
) -> Operation:
    """Create an hw.module operation backed by the generic IR."""

    input_args = [
        (port["name"], port["type"])
        for port in ports
        if port["direction"] == "in"
    ]
    module_region = region or Region([Block(arguments=input_args)])
    return Operation(
        "hw.module",
        regions=[module_region],
        properties={
            "sym_name": name,
            "ports": [dict(port) for port in ports],
        },
    )

