"""Pass manager and constant folding pass."""

from __future__ import annotations

from typing import Callable, Dict, List, Optional

from .ir import IntegerType, Operation
from .pattern import GreedyPatternApplier, RewritePattern


class Pass:
    """Base class for module passes."""

    def __init__(self, name: str) -> None:
        self.name = name
        self._statistics: Dict[str, int] = {}

    def run(self, module: Operation) -> bool:
        raise NotImplementedError

    def set_statistic(self, name: str, value: int) -> None:
        self._statistics[name] = value

    def get_statistic(self, name: str) -> int:
        return self._statistics.get(name, 0)


class PassManager:
    """Very small sequential pass manager."""

    def __init__(self) -> None:
        self._passes: List[Pass] = []

    def add_pass(self, the_pass: Pass) -> None:
        self._passes.append(the_pass)

    def run(self, module: Operation) -> None:
        for the_pass in self._passes:
            the_pass.run(module)


class _ConstantFoldPattern(RewritePattern):
    """Fold integer arithmetic with constant operands."""

    _BINARY_FNS: Dict[str, Callable[[int, int], int]] = {
        "arith.addi": lambda lhs, rhs: lhs + rhs,
        "arith.subi": lambda lhs, rhs: lhs - rhs,
        "arith.muli": lambda lhs, rhs: lhs * rhs,
    }

    def match_and_rewrite(self, op: Operation, rewriter) -> bool:
        if op.name not in self._BINARY_FNS:
            return False
        if len(op.operands) != 2 or not isinstance(op.result.type, IntegerType):
            return False
        lhs = self._constant_operand(op.operands[0])
        rhs = self._constant_operand(op.operands[1])
        if lhs is None or rhs is None:
            return False
        width = op.result.type.width
        mask = (1 << width) - 1
        folded = self._BINARY_FNS[op.name](lhs, rhs) & mask
        rewriter.replace_op_with_constant(op, folded)
        return True

    @staticmethod
    def _constant_operand(value) -> Optional[int]:
        owner = getattr(value, "owner", None)
        if owner is None or owner.name != "arith.constant":
            return None
        return owner.attributes["value"]


class ConstantFolding(Pass):
    """Greedy constant folding pass for arithmetic ops."""

    def __init__(self) -> None:
        super().__init__("constant-folding")
        self._applier = GreedyPatternApplier([_ConstantFoldPattern()])

    def run(self, module: Operation) -> bool:
        rewrites = self._applier.run(module)
        self.set_statistic("num_folded", rewrites)
        return rewrites > 0

