"""Cycle-accurate simulator for the CIRCT subset used by the repo."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, Iterable, List, Sequence

from mlir.ir import IntegerType, ModuleOp, Operation, Value

from .hw_dialect import Direction, HWModuleOp


def _value_name(value: Value) -> str:
    if value.name_hint is None:
        raise ValueError("simulator requires named SSA values")
    return value.name_hint


def _mask_for_type(value_type) -> int | None:
    if isinstance(value_type, IntegerType):
        return (1 << value_type.width) - 1
    return None


def _masked(value: int, value_type) -> int:
    mask = _mask_for_type(value_type)
    if mask is None:
        return value
    return value & mask


@dataclass
class SimulationResult:
    outputs: Dict[str, int]
    state: Dict[str, int]


class CircuitSimulator:
    """Evaluate parsed hw.module operations cycle by cycle."""

    def __init__(self, module: HWModuleOp | Operation | ModuleOp) -> None:
        if isinstance(module, HWModuleOp):
            self._module = module.operation
        elif isinstance(module, ModuleOp):
            if len(module.body.operations) != 1 or module.body.operations[0].name != "hw.module":
                raise ValueError("module wrapper must contain exactly one hw.module")
            self._module = module.body.operations[0]
        else:
            self._module = module
        if self._module.name != "hw.module":
            raise ValueError("simulator expects an hw.module")
        self._entry_block = self._module.regions[0].entry_block
        self._ports = list(self._module.properties["ports"])
        self._output_ports = [port for port in self._ports if port["direction"] == Direction.OUTPUT.value]
        self._registers: Dict[str, int] = {}
        self._initial_registers: Dict[str, int] = {}
        self._initialize_registers()

    @property
    def state(self) -> Dict[str, int]:
        return dict(self._registers)

    def reset(self) -> None:
        self._registers = dict(self._initial_registers)

    def cycle(self, inputs: Dict[str, int]) -> SimulationResult:
        environment = self._seed_environment(inputs)
        pending_registers: Dict[str, int] = {}
        for op in self._entry_block.operations:
            if op.name == "seq.compreg":
                environment[_value_name(op.result)] = self._registers.get(_value_name(op.result), 0)

        outputs: Dict[str, int] = {}
        max_iterations = max(1, len(self._entry_block.operations) + 2)
        for _ in range(max_iterations):
            changed = False
            for op in self._entry_block.operations:
                if op.name == "seq.compreg":
                    continue
                if op.name == "hw.output":
                    outputs.update(self._evaluate_output(op, environment))
                    continue
                computed = self._evaluate_operation(op, environment)
                if computed is None:
                    continue
                name = _value_name(op.result)
                if environment.get(name) != computed:
                    environment[name] = computed
                    changed = True
            if not changed:
                break

        for op in self._entry_block.operations:
            if op.name != "seq.compreg":
                continue
            reg_name = _value_name(op.result)
            input_value = self._read_operand(op.operands[0], environment)
            if input_value is None:
                raise ValueError(f"unresolved next-state signal for register {reg_name}")
            if op.properties["has_reset"]:
                reset_signal = self._read_operand(op.operands[2], environment)
                if reset_signal:
                    input_value = self._read_operand(op.operands[3], environment)
                    if input_value is None:
                        raise ValueError(f"unresolved reset value for register {reg_name}")
            pending_registers[reg_name] = _masked(input_value, op.result.type)

        self._registers.update(pending_registers)
        return SimulationResult(outputs=outputs, state=self.state)

    def run(self, inputs_per_cycle: Sequence[Dict[str, int]]) -> List[SimulationResult]:
        return [self.cycle(inputs) for inputs in inputs_per_cycle]

    def _initialize_registers(self) -> None:
        for op in self._entry_block.operations:
            if op.name != "seq.compreg":
                continue
            reg_name = _value_name(op.result)
            initial = 0
            if op.properties["has_reset"]:
                reset_value = op.operands[3]
                if getattr(reset_value, "owner", None) and reset_value.owner.name in {"hw.constant", "arith.constant"}:
                    initial = int(reset_value.owner.attributes["value"])
            self._registers[reg_name] = _masked(initial, op.result.type)
        self._initial_registers = dict(self._registers)

    def _seed_environment(self, inputs: Dict[str, int]) -> Dict[str, int]:
        environment: Dict[str, int] = {}
        for port in self._ports:
            if port["direction"] != Direction.INPUT.value:
                continue
            raw_value = inputs.get(port["name"], 0)
            environment[port["name"]] = _masked(raw_value, port["type"])
        return environment

    def _evaluate_output(self, op: Operation, environment: Dict[str, int]) -> Dict[str, int]:
        values = []
        for operand in op.operands:
            resolved = self._read_operand(operand, environment)
            if resolved is None:
                return {}
            values.append(resolved)
        return {port["name"]: value for port, value in zip(self._output_ports, values)}

    def _evaluate_operation(self, op: Operation, environment: Dict[str, int]) -> int | None:
        if op.name in {"hw.constant", "arith.constant"}:
            return _masked(int(op.attributes["value"]), op.result.type)
        operand_values = [self._read_operand(operand, environment) for operand in op.operands]
        if any(value is None for value in operand_values):
            return None
        lhs = operand_values[0]
        rhs = operand_values[1] if len(operand_values) > 1 else None
        if op.name == "comb.add":
            return _masked(lhs + rhs, op.result.type)
        if op.name == "comb.and":
            return _masked(lhs & rhs, op.result.type)
        if op.name == "comb.or":
            return _masked(lhs | rhs, op.result.type)
        if op.name == "comb.xor":
            return _masked(lhs ^ rhs, op.result.type)
        if op.name == "comb.icmp":
            predicate = op.attributes["predicate"]
            if predicate == "eq":
                return 1 if lhs == rhs else 0
            if predicate == "ne":
                return 1 if lhs != rhs else 0
            if predicate == "sgt":
                return 1 if lhs > rhs else 0
            if predicate == "slt":
                return 1 if lhs < rhs else 0
            raise ValueError(f"unsupported comparison predicate: {predicate}")
        if op.name == "comb.mux":
            cond, true_value, false_value = operand_values
            return _masked(true_value if cond else false_value, op.result.type)
        raise ValueError(f"unsupported simulated op: {op.name}")

    @staticmethod
    def _read_operand(operand: Value, environment: Dict[str, int]) -> int | None:
        if operand.name_hint is None:
            return None
        return environment.get(operand.name_hint)

