"""CIRCT-style comb dialect helpers."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, Iterable, List, Sequence

from mlir.ir import IntegerType, Operation, Value


def _mask(width: int) -> int:
    return (1 << width) - 1 if width > 0 else 0


def _resolve_operand(operand: str | int, environment: Dict[str, int]) -> int:
    if isinstance(operand, int):
        return operand
    return environment[operand]


@dataclass
class _CombOp:
    operands: Sequence[str | int]
    width: int
    result_name: str | None = None

    op_name: str = ""

    def evaluate(self, environment: Dict[str, int]) -> int:
        raise NotImplementedError

    def _masked(self, value: int) -> int:
        return value & _mask(self.width)

    def _result_types(self) -> List[IntegerType]:
        return [IntegerType(self.width)]

    def _result_names(self) -> List[str]:
        return [self.result_name] if self.result_name else []

    def _value_operands(self) -> List[Value]:
        raise NotImplementedError("wrapper operations only convert through HWModuleOp")

    def to_operation(self) -> Operation:
        operand_values = list(self._value_operands())
        return Operation(
            self.op_name,
            operands=operand_values,
            result_types=self._result_types(),
            properties={"type": IntegerType(self.width)},
            result_names=self._result_names(),
        )


@dataclass
class AddOp(_CombOp):
    op_name: str = "comb.add"

    def evaluate(self, environment: Dict[str, int]) -> int:
        lhs, rhs = (_resolve_operand(operand, environment) for operand in self.operands)
        return self._masked(lhs + rhs)


@dataclass
class SubOp(_CombOp):
    op_name: str = "comb.sub"

    def evaluate(self, environment: Dict[str, int]) -> int:
        lhs, rhs = (_resolve_operand(operand, environment) for operand in self.operands)
        return self._masked(lhs - rhs)


@dataclass
class MulOp(_CombOp):
    op_name: str = "comb.mul"

    def evaluate(self, environment: Dict[str, int]) -> int:
        lhs, rhs = (_resolve_operand(operand, environment) for operand in self.operands)
        return self._masked(lhs * rhs)


@dataclass
class AndOp(_CombOp):
    op_name: str = "comb.and"

    def evaluate(self, environment: Dict[str, int]) -> int:
        lhs, rhs = (_resolve_operand(operand, environment) for operand in self.operands)
        return self._masked(lhs & rhs)


@dataclass
class OrOp(_CombOp):
    op_name: str = "comb.or"

    def evaluate(self, environment: Dict[str, int]) -> int:
        lhs, rhs = (_resolve_operand(operand, environment) for operand in self.operands)
        return self._masked(lhs | rhs)


@dataclass
class XorOp(_CombOp):
    op_name: str = "comb.xor"

    def evaluate(self, environment: Dict[str, int]) -> int:
        lhs, rhs = (_resolve_operand(operand, environment) for operand in self.operands)
        return self._masked(lhs ^ rhs)


@dataclass
class IcmpOp(_CombOp):
    predicate: str = "eq"
    op_name: str = "comb.icmp"

    def __init__(
        self,
        operands: Sequence[str | int],
        width: int,
        predicate: str = "eq",
        result_name: str | None = None,
    ) -> None:
        super().__init__(operands=operands, width=width, result_name=result_name)
        self.predicate = predicate

    def evaluate(self, environment: Dict[str, int]) -> int:
        lhs, rhs = (_resolve_operand(operand, environment) for operand in self.operands)
        if self.predicate == "eq":
            return 1 if lhs == rhs else 0
        if self.predicate == "ne":
            return 1 if lhs != rhs else 0
        if self.predicate == "sgt":
            return 1 if lhs > rhs else 0
        if self.predicate == "slt":
            return 1 if lhs < rhs else 0
        raise ValueError(f"unsupported comparison predicate: {self.predicate}")

    def _result_types(self) -> List[IntegerType]:
        return [IntegerType(1)]

    def to_operation(self) -> Operation:
        operand_values = list(self._value_operands())
        return Operation(
            self.op_name,
            operands=operand_values,
            result_types=self._result_types(),
            attributes={"predicate": self.predicate},
            properties={"operand_type": IntegerType(self.width)},
            result_names=self._result_names(),
        )


@dataclass
class MuxOp(_CombOp):
    op_name: str = "comb.mux"

    def evaluate(self, environment: Dict[str, int]) -> int:
        sel, true_value, false_value = (
            _resolve_operand(operand, environment) for operand in self.operands
        )
        return self._masked(true_value if sel else false_value)


SUPPORTED_COMB_OPS = {
    "comb.add",
    "comb.and",
    "comb.icmp",
    "comb.mux",
    "comb.or",
    "comb.xor",
}

