"""CIRCT-style hw dialect wrappers built on the shared MLIR IR."""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from pathlib import Path
from typing import Dict, Iterable, List, Sequence

from mlir import parse
from mlir.ir import ClockType as _ClockType
from mlir.ir import IntegerType, Operation, make_hw_module_op


class Direction(str, Enum):
    """Hardware port direction."""

    INPUT = "in"
    OUTPUT = "out"


IntType = IntegerType
ClockType = _ClockType


@dataclass(frozen=True)
class Port:
    """Hardware module port description."""

    name: str
    port_type: object
    direction: Direction


@dataclass
class ConstantOp:
    """Convenience wrapper for hw.constant."""

    value: int
    width: int
    result_name: str | None = None

    def evaluate(self, _environment: Dict[str, int] | None = None) -> int:
        return self.value & ((1 << self.width) - 1)

    def to_operation(self) -> Operation:
        return Operation(
            "hw.constant",
            result_types=[IntegerType(self.width)],
            attributes={"value": self.value},
            properties={"type": IntegerType(self.width)},
            result_names=[self.result_name] if self.result_name else [],
        )


@dataclass
class OutputOp:
    """Convenience wrapper for hw.output."""

    operands: Sequence[str]
    width: int | None = None

    def to_operation(self, default_width: int = 1) -> Operation:
        output_type = IntegerType(self.width or default_width)
        return Operation("hw.output", operands=[], properties={"type": output_type})


class HWModuleOp:
    """Thin wrapper around a generic hw.module operation."""

    def __init__(
        self,
        name: str | None = None,
        ports: Sequence[Port] | None = None,
        body: Sequence[Operation | ConstantOp] | None = None,
        operation: Operation | None = None,
    ) -> None:
        if operation is not None:
            self.operation = operation
            return
        if name is None or ports is None:
            raise ValueError("name and ports are required when constructing an hw module")
        raw_ports = [
            {"name": port.name, "type": port.port_type, "direction": port.direction.value}
            for port in ports
        ]
        self.operation = make_hw_module_op(name, raw_ports)
        if body:
            for item in body:
                if isinstance(item, Operation):
                    self.operation.regions[0].entry_block.append_op(item)
                elif hasattr(item, "to_operation"):
                    built = item.to_operation()
                    self.operation.regions[0].entry_block.append_op(built)
                else:
                    raise TypeError(f"unsupported hw.module body item: {item!r}")

    @classmethod
    def from_operation(cls, operation: Operation) -> "HWModuleOp":
        if operation.name != "hw.module":
            raise ValueError("operation is not an hw.module")
        return cls(operation=operation)

    @property
    def name(self) -> str:
        return self.operation.properties["sym_name"]

    @property
    def ports(self) -> List[Port]:
        return [
            Port(
                name=port["name"],
                port_type=port["type"],
                direction=Direction(port["direction"]),
            )
            for port in self.operation.properties["ports"]
        ]

    @property
    def body(self) -> List[Operation]:
        return list(self.operation.regions[0].entry_block.operations)

    def to_operation(self) -> Operation:
        return self.operation


def parse_hw_module(text: str) -> HWModuleOp:
    """Parse an hw.module or wrapped module and return the first hardware module."""

    module = parse(text)
    for op in module.body.operations:
        if op.name == "hw.module":
            return HWModuleOp.from_operation(op)
    raise ValueError("no hw.module found in input")


def load_hw_module(path: str | Path) -> HWModuleOp:
    """Load and parse an hw.module from disk."""

    return parse_hw_module(Path(path).read_text(encoding="utf-8"))

