"""K-inspired semantic rule engine for circuit evaluation."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Callable, Dict, List, Optional, Sequence

try:
    from circt import HWModuleOp
    from mlir.ir import IntegerType, ModuleOp, Operation, Value
except ImportError:  # pragma: no cover - package import shim
    from src.circt import HWModuleOp
    from src.mlir.ir import IntegerType, ModuleOp, Operation, Value


def _value_name(value: Value) -> str:
    if value.name_hint is None:
        raise ValueError("kimulator requires named SSA values")
    return value.name_hint


def _masked(value: int, value_type) -> int:
    if isinstance(value_type, IntegerType):
        return value & ((1 << value_type.width) - 1)
    return value


@dataclass(frozen=True)
class TraceEvent:
    """One semantic rule application."""

    cycle: int
    rule: str
    op_name: str
    target: str
    value: int | None = None


@dataclass(frozen=True)
class CycleTrace:
    """Per-cycle execution summary."""

    cycle: int
    inputs: Dict[str, int]
    outputs: Dict[str, int]
    state_before: Dict[str, int]
    state_after: Dict[str, int]


@dataclass
class KimulatorTrace:
    """Collected execution trace."""

    events: List[TraceEvent] = field(default_factory=list)
    cycles: List[CycleTrace] = field(default_factory=list)

    @property
    def final_outputs(self) -> Dict[str, int]:
        if not self.cycles:
            return {}
        return dict(self.cycles[-1].outputs)

    @property
    def final_state(self) -> Dict[str, int]:
        if not self.cycles:
            return {}
        return dict(self.cycles[-1].state_after)


@dataclass
class _ExecutionContext:
    cycle: int
    environment: Dict[str, int]
    outputs: Dict[str, int]
    state: Dict[str, int]
    pending_state: Dict[str, int]
    output_ports: List[Dict[str, object]]
    trace: KimulatorTrace

    def record(self, rule: str, op_name: str, target: str, value: int | None = None) -> None:
        self.trace.events.append(TraceEvent(self.cycle, rule, op_name, target, value))


class SemanticRule:
    """Declarative semantic rule used by the Kimulator."""

    def __init__(
        self,
        name: str,
        applies: Callable[[Operation], bool],
        execute: Callable[["_ExecutionContext", Operation], bool],
    ) -> None:
        self.name = name
        self._applies = applies
        self._execute = execute

    def try_apply(self, context: _ExecutionContext, op: Operation) -> bool:
        if not self._applies(op):
            return False
        return self._execute(context, op)


class Kimulator:
    """Evaluates hw/comb/seq circuits through explicit semantic rules."""

    def __init__(self) -> None:
        self._read_rule = SemanticRule(
            "seq.read",
            lambda op: op.name == "seq.compreg",
            self._read_register,
        )
        self._comb_rules = [
            SemanticRule("const.eval", lambda op: op.name in {"hw.constant", "arith.constant"}, self._eval_constant),
            SemanticRule("comb.binary", lambda op: op.name in {"comb.add", "comb.and", "comb.or", "comb.xor"}, self._eval_binary),
            SemanticRule("comb.icmp", lambda op: op.name == "comb.icmp", self._eval_icmp),
            SemanticRule("comb.mux", lambda op: op.name == "comb.mux", self._eval_mux),
            SemanticRule("hw.output", lambda op: op.name == "hw.output", self._eval_output),
        ]
        self._commit_rule = SemanticRule(
            "seq.write",
            lambda op: op.name == "seq.compreg",
            self._commit_register,
        )

    def run(self, module: HWModuleOp | Operation | ModuleOp, inputs_per_cycle: Sequence[Dict[str, int]]) -> KimulatorTrace:
        hw_module = self._unwrap_module(module)
        trace = KimulatorTrace()
        state = self._initial_state(hw_module)
        output_ports = [port for port in hw_module.properties["ports"] if port["direction"] == "out"]
        body = hw_module.regions[0].entry_block.operations

        for cycle_index, inputs in enumerate(inputs_per_cycle, start=1):
            environment = self._seed_environment(hw_module, inputs)
            context = _ExecutionContext(
                cycle=cycle_index,
                environment=environment,
                outputs={},
                state=dict(state),
                pending_state={},
                output_ports=output_ports,
                trace=trace,
            )
            for op in body:
                self._read_rule.try_apply(context, op)
            max_iterations = max(1, len(body) + 2)
            for _ in range(max_iterations):
                changed = False
                for op in body:
                    if op.name == "seq.compreg":
                        continue
                    for rule in self._comb_rules:
                        if rule.try_apply(context, op):
                            changed = True
                            break
                if not changed:
                    break
            for op in body:
                self._commit_rule.try_apply(context, op)
            state.update(context.pending_state)
            trace.cycles.append(
                CycleTrace(
                    cycle=cycle_index,
                    inputs=dict(inputs),
                    outputs=dict(context.outputs),
                    state_before=context.state,
                    state_after=dict(state),
                )
            )
        return trace

    def evaluate(self, module: HWModuleOp | Operation | ModuleOp, inputs: Dict[str, int]) -> Dict[str, int]:
        return self.run(module, [inputs]).final_outputs

    def _unwrap_module(self, module: HWModuleOp | Operation | ModuleOp) -> Operation:
        if isinstance(module, HWModuleOp):
            return module.operation
        if isinstance(module, ModuleOp):
            if len(module.body.operations) != 1 or module.body.operations[0].name != "hw.module":
                raise ValueError("wrapper module must contain exactly one hw.module")
            return module.body.operations[0]
        if module.name != "hw.module":
            raise ValueError("kimulator expects an hw.module")
        return module

    def _initial_state(self, hw_module: Operation) -> Dict[str, int]:
        state: Dict[str, int] = {}
        for op in hw_module.regions[0].entry_block.operations:
            if op.name != "seq.compreg":
                continue
            reg_name = _value_name(op.result)
            initial = 0
            if op.properties["has_reset"]:
                reset_value = op.operands[3]
                if getattr(reset_value, "owner", None) and reset_value.owner.name in {"hw.constant", "arith.constant"}:
                    initial = int(reset_value.owner.attributes["value"])
            state[reg_name] = _masked(initial, op.result.type)
        return state

    def _seed_environment(self, hw_module: Operation, inputs: Dict[str, int]) -> Dict[str, int]:
        environment: Dict[str, int] = {}
        for port in hw_module.properties["ports"]:
            if port["direction"] != "in":
                continue
            raw_value = inputs.get(port["name"], 0)
            environment[port["name"]] = _masked(raw_value, port["type"])
        return environment

    @staticmethod
    def _read_operand(value: Value, environment: Dict[str, int]) -> Optional[int]:
        if value.name_hint is None:
            return None
        return environment.get(value.name_hint)

    def _bind_result(self, context: _ExecutionContext, op: Operation, value: int) -> bool:
        target = _value_name(op.result)
        value = _masked(value, op.result.type)
        if context.environment.get(target) == value:
            return False
        context.environment[target] = value
        context.record("bind", op.name, target, value)
        return True

    def _read_register(self, context: _ExecutionContext, op: Operation) -> bool:
        target = _value_name(op.result)
        value = context.state[target]
        if context.environment.get(target) == value:
            return False
        context.environment[target] = value
        context.record("seq.read", op.name, target, value)
        return True

    def _eval_constant(self, context: _ExecutionContext, op: Operation) -> bool:
        return self._bind_result(context, op, int(op.attributes["value"]))

    def _eval_binary(self, context: _ExecutionContext, op: Operation) -> bool:
        lhs = self._read_operand(op.operands[0], context.environment)
        rhs = self._read_operand(op.operands[1], context.environment)
        if lhs is None or rhs is None:
            return False
        if op.name == "comb.add":
            value = lhs + rhs
        elif op.name == "comb.and":
            value = lhs & rhs
        elif op.name == "comb.or":
            value = lhs | rhs
        elif op.name == "comb.xor":
            value = lhs ^ rhs
        else:
            raise ValueError(f"unsupported binary op: {op.name}")
        return self._bind_result(context, op, value)

    def _eval_icmp(self, context: _ExecutionContext, op: Operation) -> bool:
        lhs = self._read_operand(op.operands[0], context.environment)
        rhs = self._read_operand(op.operands[1], context.environment)
        if lhs is None or rhs is None:
            return False
        predicate = op.attributes["predicate"]
        if predicate == "eq":
            value = 1 if lhs == rhs else 0
        elif predicate == "ne":
            value = 1 if lhs != rhs else 0
        elif predicate == "sgt":
            value = 1 if lhs > rhs else 0
        elif predicate == "slt":
            value = 1 if lhs < rhs else 0
        else:
            raise ValueError(f"unsupported comparison predicate: {predicate}")
        return self._bind_result(context, op, value)

    def _eval_mux(self, context: _ExecutionContext, op: Operation) -> bool:
        cond = self._read_operand(op.operands[0], context.environment)
        true_value = self._read_operand(op.operands[1], context.environment)
        false_value = self._read_operand(op.operands[2], context.environment)
        if cond is None or true_value is None or false_value is None:
            return False
        value = true_value if cond else false_value
        return self._bind_result(context, op, value)

    def _eval_output(self, context: _ExecutionContext, op: Operation) -> bool:
        resolved_values: List[int] = []
        for operand in op.operands:
            value = self._read_operand(operand, context.environment)
            if value is None:
                return False
            resolved_values.append(value)
        changed = False
        for port, value in zip(context.output_ports, resolved_values):
            if context.outputs.get(port["name"]) != value:
                context.outputs[port["name"]] = value
                context.record("hw.output", op.name, str(port["name"]), value)
                changed = True
        return changed

    def _commit_register(self, context: _ExecutionContext, op: Operation) -> bool:
        reg_name = _value_name(op.result)
        next_value = self._read_operand(op.operands[0], context.environment)
        if next_value is None:
            return False
        if op.properties["has_reset"]:
            reset_signal = self._read_operand(op.operands[2], context.environment)
            if reset_signal:
                reset_value = self._read_operand(op.operands[3], context.environment)
                if reset_value is None:
                    return False
                next_value = reset_value
        next_value = _masked(next_value, op.result.type)
        context.pending_state[reg_name] = next_value
        context.record("seq.write", op.name, reg_name, next_value)
        return True

