"""Stateful circuit executor built on the CIRCT simulator."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, List, Sequence

try:
    from circt import CircuitSimulator, HWModuleOp
    from mlir.ir import ModuleOp, Operation
except ImportError:  # pragma: no cover - package import shim
    from src.circt import CircuitSimulator, HWModuleOp
    from src.mlir.ir import ModuleOp, Operation


@dataclass(frozen=True)
class StateSnapshot:
    """Visible state after a single cycle."""

    cycle: int
    inputs: Dict[str, int]
    outputs: Dict[str, int]
    state: Dict[str, int]


class StatefulCircuitExecutor:
    """Small stateful execution wrapper around the hardware simulator."""

    def __init__(self, module: HWModuleOp | Operation | ModuleOp) -> None:
        self._simulator = CircuitSimulator(module)
        self._cycle = 0

    @property
    def state(self) -> Dict[str, int]:
        return self._simulator.state

    def reset(self) -> None:
        self._simulator.reset()
        self._cycle = 0

    def step(self, inputs: Dict[str, int]) -> StateSnapshot:
        result = self._simulator.cycle(inputs)
        self._cycle += 1
        return StateSnapshot(
            cycle=self._cycle,
            inputs=dict(inputs),
            outputs=dict(result.outputs),
            state=dict(result.state),
        )

    def run(self, inputs_per_cycle: Sequence[Dict[str, int]]) -> List[StateSnapshot]:
        return [self.step(inputs) for inputs in inputs_per_cycle]

