"""Small compatibility layer for symbolic kernel-like IR snippets."""

from __future__ import annotations

from dataclasses import dataclass
from typing import List, Sequence


@dataclass(frozen=True)
class KernelInstruction:
    name: str
    opcode: str
    inputs: Sequence[str]
    output: str
    latency: int = 1


class KernelOp:
    """Minimal operation container used by simple semantic experiments."""

    def __init__(self, name: str) -> None:
        self.name = name
        self.instructions: List[KernelInstruction] = []

    def add_operation(self, name: str, opcode: str, inputs: Sequence[str], output: str, latency: int = 1) -> None:
        self.instructions.append(KernelInstruction(name, opcode, list(inputs), output, latency))

    def total_operations(self) -> int:
        return len(self.instructions)

    def critical_path_latency(self) -> int:
        return sum(instruction.latency for instruction in self.instructions)

