"""Symbol and type analysis for the shared MLIR/CIRCT IR."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional

try:
    from mlir.ir import Operation, Type
except ImportError:  # pragma: no cover - package import shim
    from src.mlir.ir import Operation, Type


@dataclass(frozen=True)
class SymbolRecord:
    """A resolved symbol in the parsed IR."""

    name: str
    kind: str
    owner: Operation


class SymbolTable:
    """Collects named IR entities from modules and circuits."""

    def __init__(self, root: Operation) -> None:
        self._root = root
        self._symbols: Dict[str, SymbolRecord] = {}
        self._build()

    def _build(self) -> None:
        for op in self._root.walk():
            symbol_name = op.properties.get("sym_name")
            if not symbol_name:
                continue
            if op.name == "func.func":
                kind = "function"
            elif op.name == "hw.module":
                kind = "hw.module"
            else:
                kind = op.name
            self._symbols[symbol_name] = SymbolRecord(symbol_name, kind, op)

    def resolve(self, name: str) -> Optional[SymbolRecord]:
        return self._symbols.get(name)

    def count(self, kind: str | None = None) -> int:
        if kind is None:
            return len(self._symbols)
        return sum(1 for record in self._symbols.values() if record.kind == kind)

    def names(self, kind: str | None = None) -> List[str]:
        return [
            record.name
            for record in self._symbols.values()
            if kind is None or record.kind == kind
        ]


class TypeAnalyzer:
    """Looks up types and attributes through the parsed IR."""

    def __init__(self, root: Operation) -> None:
        self._root = root
        self._symbols = SymbolTable(root)

    def function_result_type(self, name: str) -> Type:
        symbol = self._symbols.resolve(name)
        if symbol is None or symbol.kind != "function":
            raise KeyError(f"unknown function symbol: {name}")
        result_types = symbol.owner.properties["result_types"]
        if not result_types:
            raise ValueError(f"function {name} has no results")
        return result_types[0]

    def port_type(self, module_name: str, port_name: str) -> Type:
        symbol = self._symbols.resolve(module_name)
        if symbol is None or symbol.kind != "hw.module":
            raise KeyError(f"unknown hw.module symbol: {module_name}")
        for port in symbol.owner.properties["ports"]:
            if port["name"] == port_name:
                return port["type"]
        raise KeyError(f"unknown port {port_name} on {module_name}")

    def first_integer_attribute(self) -> int:
        for op in self._root.walk():
            if "value" in op.attributes and isinstance(op.attributes["value"], int):
                return int(op.attributes["value"])
        raise ValueError("no integer attributes found")
